package monitor

import (
	"context"
	"encoding/json"
	"log/slog"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
	"time"

	"nhooyr.io/websocket"
)

func TestHandleWS_SnapshotOnConnect(t *testing.T) {
	events := make(chan ServerEvent, 8)
	hub := NewHub(slog.Default(), events, func() []BackendStatus {
		return []BackendStatus{{
			Name:    "test",
			Model:   "some-model",
			Healthy: true,
			Port:    12345,
		}}
	})
	hub.gpus = nil
	hub.Start()
	defer hub.Stop()

	srv := httptest.NewServer(http.HandlerFunc(HandleWS(hub)))
	defer srv.Close()

	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	wsURL := strings.Replace(srv.URL, "http://", "ws://", 1)
	conn, _, err := websocket.Dial(ctx, wsURL, nil)
	if err != nil {
		t.Fatalf("dial: %v", err)
	}
	defer conn.CloseNow()

	_, data, err := conn.Read(ctx)
	if err != nil {
		t.Fatalf("read snapshot: %v", err)
	}

	var msg map[string]json.RawMessage
	if err := json.Unmarshal(data, &msg); err != nil {
		t.Fatalf("unmarshal snapshot: %v", err)
	}

	var typ string
	if err := json.Unmarshal(msg["type"], &typ); err != nil || typ != "snapshot" {
		t.Errorf("first message type: got %q, want %q", typ, "snapshot")
	}

	var backends map[string]json.RawMessage
	if err := json.Unmarshal(msg["backends"], &backends); err != nil {
		t.Fatalf("backends field: %v", err)
	}
	if _, ok := backends["test"]; !ok {
		t.Error("expected backend 'test' in snapshot")
	}

	var gpus []json.RawMessage
	if err := json.Unmarshal(msg["gpus"], &gpus); err != nil {
		t.Fatalf("gpus field: %v", err)
	}
	// No GPUs in test environment.
	if len(gpus) != 0 {
		t.Errorf("gpus: got %d, want 0", len(gpus))
	}
}

func TestHandleWS_MetricsForwarded(t *testing.T) {
	events := make(chan ServerEvent, 8)
	hub := NewHub(slog.Default(), events, func() []BackendStatus { return nil })
	hub.gpus = nil
	hub.Start()
	defer hub.Stop()

	srv := httptest.NewServer(http.HandlerFunc(HandleWS(hub)))
	defer srv.Close()

	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	wsURL := strings.Replace(srv.URL, "http://", "ws://", 1)
	conn, _, err := websocket.Dial(ctx, wsURL, nil)
	if err != nil {
		t.Fatalf("dial: %v", err)
	}
	defer conn.CloseNow()

	// Drain snapshot.
	if _, _, err := conn.Read(ctx); err != nil {
		t.Fatalf("read snapshot: %v", err)
	}

	// Inject a metrics message after a short delay to allow the handler to
	// reach its select loop.
	go func() {
		time.Sleep(30 * time.Millisecond)
		hub.broadcast(HubMessage{
			Kind: MsgMetricsTick,
			Metrics: &BackendMetrics{
				Name:              "local",
				KVCacheUsageRatio: 0.5,
				TokensPerSecond:   42.0,
			},
		})
	}()

	// Read until we get a metrics message (poll ticks may also arrive).
	deadline := time.After(3 * time.Second)
	for {
		var msg map[string]json.RawMessage
		_, data, readErr := conn.Read(ctx)
		if readErr != nil {
			t.Fatalf("read: %v", readErr)
		}
		if err := json.Unmarshal(data, &msg); err != nil {
			t.Fatalf("unmarshal: %v", err)
		}
		var typ string
		json.Unmarshal(msg["type"], &typ) //nolint:errcheck
		if typ != "metrics" {
			select {
			case <-deadline:
				t.Fatal("timeout waiting for metrics message")
			default:
				continue
			}
		}

		var kvPct float64
		if err := json.Unmarshal(msg["kv_cache_pct"], &kvPct); err != nil {
			t.Fatalf("kv_cache_pct: %v", err)
		}
		if kvPct != 50.0 {
			t.Errorf("kv_cache_pct: got %v, want 50.0", kvPct)
		}
		return
	}
}

func TestHandleWS_HubStop_ClosesConnection(t *testing.T) {
	events := make(chan ServerEvent, 8)
	hub := NewHub(slog.Default(), events, func() []BackendStatus { return nil })
	hub.gpus = nil
	hub.Start()

	srv := httptest.NewServer(http.HandlerFunc(HandleWS(hub)))
	defer srv.Close()

	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	wsURL := strings.Replace(srv.URL, "http://", "ws://", 1)
	conn, _, err := websocket.Dial(ctx, wsURL, nil)
	if err != nil {
		t.Fatalf("dial: %v", err)
	}
	defer conn.CloseNow()

	// Drain snapshot.
	if _, _, err := conn.Read(ctx); err != nil {
		t.Fatalf("read snapshot: %v", err)
	}

	// Stop the hub — the websocket handler must close the connection.
	hub.Stop()

	// The next read should fail because the server closed the connection.
	readCtx, readCancel := context.WithTimeout(context.Background(), 3*time.Second)
	defer readCancel()
	_, _, err = conn.Read(readCtx)
	if err == nil {
		t.Error("expected connection close after hub stop, got nil error")
	}
}

func TestHandlePage(t *testing.T) {
	req := httptest.NewRequest(http.MethodGet, "/monitor", nil)
	w := httptest.NewRecorder()
	HandlePage(w, req)

	resp := w.Result()
	if resp.StatusCode != http.StatusOK {
		t.Errorf("status: got %d, want 200", resp.StatusCode)
	}
	ct := resp.Header.Get("Content-Type")
	if ct != "text/html; charset=utf-8" {
		t.Errorf("content-type: got %q, want %q", ct, "text/html; charset=utf-8")
	}
	if w.Body.Len() == 0 {
		t.Error("response body is empty")
	}
}

package monitor

import (
	"context"
	"io"
	"log/slog"
	"net/http"
	"sync"
	"sync/atomic"
	"time"
)

// HubMessageKind identifies the type of a HubMessage.
type HubMessageKind int

const (
	MsgSnapshot    HubMessageKind = iota // initial state snapshot for a new subscriber
	MsgMetricsTick                       // backend metrics polled from /metrics + /slots
	MsgGPUTick                           // GPU hardware metrics polled from sysfs
	MsgServerEvent                       // structured event relayed from eventParser
	MsgStateChange                       // backend health state changed
)

// BackendMetrics is the latest polled state for one managed backend.
type BackendMetrics struct {
	Name                  string
	KVCacheUsageRatio     float64
	RequestsProcessing    int
	RequestsPending       int
	TokensPerSecond       float64
	PromptTokensPerSecond float64
	TokensPredictedTotal  int64
	PromptTokensTotal     int64
	Slots                 []Slot
}

// HubSnapshot is the full current state, delivered to new subscribers.
type HubSnapshot struct {
	Backends []BackendMetrics
	GPUs     []GPUMetrics
}

// HubMessage is a tagged message sent to subscribers.
type HubMessage struct {
	Kind    HubMessageKind
	Snap    *HubSnapshot    // MsgSnapshot
	Metrics *BackendMetrics // MsgMetricsTick
	GPUs    []GPUMetrics    // MsgGPUTick
	Event   *ServerEvent    // MsgServerEvent
	Backend string          // MsgStateChange
	Healthy bool            // MsgStateChange
}

// Hub subscribes to the event channel from Manager, polls each backend's HTTP
// endpoints and GPU sysfs files every second, and fans out to subscribers.
type Hub struct {
	log        *slog.Logger
	events     <-chan ServerEvent
	snapshotFn func() []BackendStatus
	gpus       []GPUInfo

	mu      sync.RWMutex
	metrics map[string]*BackendMetrics
	gpuData []GPUMetrics

	subsMu sync.Mutex
	subs   map[uint64]chan HubMessage
	nextID atomic.Uint64

	ctx    context.Context
	cancel context.CancelFunc
	wg     sync.WaitGroup

	client *http.Client
}

// NewHub creates a Hub. snapshotFn is called on every poll tick to obtain
// current backend addresses (Manager.Snapshot satisfies this). Call Start to
// begin the event relay and poll loop.
func NewHub(log *slog.Logger, events <-chan ServerEvent, snapshotFn func() []BackendStatus) *Hub {
	ctx, cancel := context.WithCancel(context.Background())
	h := &Hub{
		log:        log,
		events:     events,
		snapshotFn: snapshotFn,
		metrics:    make(map[string]*BackendMetrics),
		subs:       make(map[uint64]chan HubMessage),
		ctx:        ctx,
		cancel:     cancel,
		client:     &http.Client{Timeout: 3 * time.Second},
	}
	h.gpus = DiscoverGPUs()
	return h
}

// Start launches the event relay and poll goroutines.
func (h *Hub) Start() {
	h.wg.Add(2)
	go h.relayEvents()
	go h.pollLoop()
}

// Stop cancels both goroutines, waits for them to exit, then closes all
// subscriber channels. No goroutines are leaked after Stop returns.
func (h *Hub) Stop() {
	h.cancel()
	h.wg.Wait()

	h.subsMu.Lock()
	for id, ch := range h.subs {
		close(ch)
		delete(h.subs, id)
	}
	h.subsMu.Unlock()
}

// Subscribe registers a subscriber. The returned channel (buffered 64) receives
// a MsgSnapshot immediately, then subsequent messages as they arrive. The
// returned func removes the subscriber; Stop closes the channel.
func (h *Hub) Subscribe() (<-chan HubMessage, func()) {
	ch := make(chan HubMessage, 64)
	id := h.nextID.Add(1)

	h.subsMu.Lock()
	h.subs[id] = ch
	h.subsMu.Unlock()

	snap := h.Snapshot()
	select {
	case ch <- HubMessage{Kind: MsgSnapshot, Snap: &snap}:
	default:
	}

	return ch, func() {
		h.subsMu.Lock()
		delete(h.subs, id)
		h.subsMu.Unlock()
	}
}

// Statuses returns the current runtime state of all managed backends by
// delegating to the snapshotFn provided at construction. Safe to call
// concurrently.
func (h *Hub) Statuses() []BackendStatus {
	return h.snapshotFn()
}

// Snapshot returns a copy of the current full state synchronously.
func (h *Hub) Snapshot() HubSnapshot {
	h.mu.RLock()
	defer h.mu.RUnlock()

	backends := make([]BackendMetrics, 0, len(h.metrics))
	for _, m := range h.metrics {
		cp := *m
		backends = append(backends, cp)
	}
	gpuCopy := make([]GPUMetrics, len(h.gpuData))
	copy(gpuCopy, h.gpuData)
	return HubSnapshot{Backends: backends, GPUs: gpuCopy}
}

func (h *Hub) relayEvents() {
	defer h.wg.Done()
	for {
		select {
		case <-h.ctx.Done():
			return
		case ev, ok := <-h.events:
			if !ok {
				return
			}
			ev2 := ev
			h.broadcast(HubMessage{Kind: MsgServerEvent, Event: &ev2})
		}
	}
}

func (h *Hub) pollLoop() {
	defer h.wg.Done()
	ticker := time.NewTicker(time.Second)
	defer ticker.Stop()
	for {
		select {
		case <-h.ctx.Done():
			return
		case <-ticker.C:
			h.poll()
		}
	}
}

func (h *Hub) poll() {
	for _, b := range h.snapshotFn() {
		if b.Port == 0 {
			continue
		}
		m := h.fetchBackend(b)
		h.mu.Lock()
		h.metrics[b.Name] = m
		h.mu.Unlock()
		h.broadcast(HubMessage{Kind: MsgMetricsTick, Metrics: m})
	}

	gpuMetrics := ReadGPUMetrics(h.gpus)
	h.mu.Lock()
	h.gpuData = gpuMetrics
	h.mu.Unlock()
	if len(gpuMetrics) > 0 {
		h.broadcast(HubMessage{Kind: MsgGPUTick, GPUs: gpuMetrics})
	}
}

func (h *Hub) fetchBackend(b BackendStatus) *BackendMetrics {
	m := &BackendMetrics{Name: b.Name}
	base := "http://localhost:" + itoa(b.Port)

	if data, err := h.fetch(base + "/metrics"); err == nil {
		g := ParsePrometheusGauges(string(data))
		m.KVCacheUsageRatio = g["llama_kv_cache_usage_ratio"]
		m.RequestsProcessing = int(g["llama_requests_processing"])
		m.RequestsPending = int(g["llama_requests_pending"])
		m.TokensPerSecond = g["llama_tokens_predicted_per_second"]
		m.PromptTokensPerSecond = g["llama_prompt_tokens_per_second"]
		m.TokensPredictedTotal = int64(g["llama_tokens_predicted_total"])
		m.PromptTokensTotal = int64(g["llama_prompt_tokens_total"])
	} else {
		h.log.Debug("metrics fetch failed", "backend", b.Name, "error", err)
	}

	if data, err := h.fetch(base + "/slots"); err == nil {
		if slots, err := ParseSlots(data); err == nil {
			m.Slots = slots
		}
	} else {
		h.log.Debug("slots fetch failed", "backend", b.Name, "error", err)
	}

	return m
}

func (h *Hub) fetch(url string) ([]byte, error) {
	req, err := http.NewRequestWithContext(h.ctx, http.MethodGet, url, nil)
	if err != nil {
		return nil, err
	}
	resp, err := h.client.Do(req)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()
	return io.ReadAll(resp.Body)
}

func (h *Hub) broadcast(msg HubMessage) {
	h.subsMu.Lock()
	defer h.subsMu.Unlock()
	for _, ch := range h.subs {
		select {
		case ch <- msg:
		default:
			// Drop to slow consumer.
		}
	}
}

// itoa converts an int to its decimal string representation without importing
// the strconv package at the call site.
func itoa(n int) string {
	if n == 0 {
		return "0"
	}
	neg := n < 0
	if neg {
		n = -n
	}
	buf := make([]byte, 0, 10)
	for n > 0 {
		buf = append([]byte{byte('0' + n%10)}, buf...)
		n /= 10
	}
	if neg {
		buf = append([]byte{'-'}, buf...)
	}
	return string(buf)
}

