package cli

import (
	"context"
	"encoding/json"
	"fmt"
	"log/slog"
	"net/http"
	"os"
	"os/signal"
	"strings"
	"sync"
	"syscall"
	"time"

	"flag"

	"github.com/nogo/wire/internal"
	"github.com/nogo/wire/internal/build"
	"github.com/nogo/wire/internal/config"
	"github.com/nogo/wire/internal/gateway"
	"github.com/nogo/wire/internal/monitor"
	"github.com/nogo/wire/internal/pidfile"
	"github.com/nogo/wire/internal/process"
)

const usageText = `Usage: wire <command> [arguments]

Commands:
  start               Start the gateway (foreground)
  stop                Stop the running gateway
  status              Show backend status
  swap <backend> <model>  Hot-swap a backend's model
  build               Build and install llama-server from source (ROCm)
  remove              Remove a previous llama-server installation
  version             Print version and exit

Environment:
  WIRE_CONFIG         Config file path (default: ~/.config/wire/config.yaml)
  WIRE_LLAMA_SRC      llama.cpp source directory (default: ~/Development/llama.cpp)
  WIRE_GPU_TARGET     AMD GPU target (default: gfx1151; find yours: rocminfo | grep gfx)
  WIRE_PREFIX         Install prefix (default: ~/.local)
`

// Run dispatches CLI commands from the given argument slice (os.Args[1:]).
// It returns an exit code suitable for os.Exit.
func Run(args []string) int {
	if err := dispatch(args); err != nil {
		fmt.Fprintln(os.Stderr, "wire:", err)
		return 1
	}
	return 0
}

func dispatch(args []string) error {
	if len(args) == 0 {
		fmt.Print(usageText)
		return nil
	}
	switch args[0] {
	case "help", "--help", "-h":
		fmt.Print(usageText)
		return nil
	case "start":
		return runStart()
	case "stop":
		return runStop()
	case "status":
		return runStatus()
	case "swap":
		if len(args) < 3 {
			return fmt.Errorf("swap requires <backend> and <model>\nUsage: wire swap <backend> <model>")
		}
		return runSwap(args[1], args[2])
	case "version", "--version", "-v":
		fmt.Printf("wire %s (%s) built %s\n", internal.Version, internal.Commit, internal.BuildDate)
		return nil
	case "build":
		return runBuild(args[1:])
	case "remove":
		return runRemove(args[1:])
	default:
		fmt.Print(usageText)
		return fmt.Errorf("unknown command: %q", args[0])
	}
}

// listenURL converts the listen address from config to an http:// URL.
func listenURL(listen string) string {
	if strings.HasPrefix(listen, ":") {
		return "http://localhost" + listen
	}
	return "http://" + listen
}

func runStart() error {
	cfg, err := config.Load()
	if err != nil {
		return fmt.Errorf("loading config: %w", err)
	}

	pidPath := pidfile.Path()
	if err := pidfile.Write(pidPath); err != nil {
		return err
	}
	defer os.Remove(pidPath)

	// bgCtx drives the process manager; cancelled only after gateway drains.
	bgCtx, bgCancel := context.WithCancel(context.Background())
	defer bgCancel()

	// shutCtx is cancelled by SIGTERM/SIGINT. Its Cause is the received signal.
	shutCtx, stop := signal.NotifyContext(bgCtx, syscall.SIGTERM, syscall.SIGINT)
	defer stop()

	// sighupCh receives SIGHUP for config reload.
	sighupCh := make(chan os.Signal, 1)
	signal.Notify(sighupCh, syscall.SIGHUP)
	defer signal.Stop(sighupCh)

	mgr := process.New(cfg, slog.Default())
	if err := mgr.Start(bgCtx); err != nil {
		return fmt.Errorf("starting process manager: %w", err)
	}

	var hub *monitor.Hub
	if cfg.Monitor {
		hub = monitor.NewHub(slog.Default(), mgr.Events(), mgr.Snapshot)
		hub.Start()
		defer hub.Stop()
	}

	gw := gateway.New(cfg, mgr, hub, slog.Default())
	gwErrCh := make(chan error, 1)
	go func() { gwErrCh <- gw.ListenAndServe(shutCtx) }()

	slog.Info("wire ready", "listen", cfg.Listen, "version", internal.Version, "commit", internal.Commit)

	// swapMu serialises SIGHUP handling so overlapping reloads are dropped.
	var swapMu sync.Mutex

	for {
		select {
		case err := <-gwErrCh:
			bgCancel()
			_ = mgr.Stop()
			if err != nil {
				return fmt.Errorf("gateway error: %w", err)
			}
			return nil

		case <-shutCtx.Done():
			if cause := context.Cause(shutCtx); cause != nil {
				slog.Info("shutting down", "cause", cause)
			}
			stop() // release signal resources early
			// Wait for gateway to drain connections, then stop process manager.
			if err := <-gwErrCh; err != nil {
				slog.Error("gateway shutdown error", "error", err)
			}
			bgCancel()
			return mgr.Stop()

		case <-sighupCh:
			if !swapMu.TryLock() {
				slog.Warn("SIGHUP received while swap in progress, ignoring")
				continue
			}
			go func() {
				defer swapMu.Unlock()
				newCfg, loadErr := config.Load()
				if loadErr != nil {
					slog.Error("failed to reload config on SIGHUP", "error", loadErr)
					return
				}
				for name, b := range newCfg.Backends {
					oldB, ok := cfg.Backends[name]
					if !ok || !b.IsManaged() {
						continue
					}
					if b.Model != oldB.Model {
						slog.Info("swapping backend model", "backend", name, "old", oldB.Model, "new", b.Model)
						if swapErr := mgr.Swap(bgCtx, name, b.Model); swapErr != nil {
							slog.Error("model swap failed", "backend", name, "error", swapErr)
						}
					}
				}
				cfg = newCfg
			}()
		}
	}
}

func runStop() error {
	pidPath := pidfile.Path()
	pid, err := pidfile.Read(pidPath)
	if err != nil {
		return err
	}
	proc, err := os.FindProcess(pid)
	if err != nil {
		return fmt.Errorf("finding process %d: %w", pid, err)
	}
	if err := proc.Signal(syscall.SIGTERM); err != nil {
		return fmt.Errorf("sending SIGTERM to pid %d: %w", pid, err)
	}

	// Poll /proc/<pid> via kill -0 for up to 10 seconds.
	deadline := time.Now().Add(10 * time.Second)
	for time.Now().Before(deadline) {
		if err := proc.Signal(syscall.Signal(0)); err != nil {
			fmt.Printf("wire stopped (pid %d)\n", pid)
			return nil
		}
		time.Sleep(200 * time.Millisecond)
	}

	// Still alive: force kill.
	_ = proc.Signal(syscall.SIGKILL)
	fmt.Printf("wire force-killed (pid %d)\n", pid)
	return nil
}

func runStatus() error {
	cfg, err := config.Load()
	if err != nil {
		return fmt.Errorf("loading config: %w", err)
	}

	baseURL := listenURL(cfg.Listen)
	client := &http.Client{Timeout: 5 * time.Second}

	healthResp, err := client.Get(baseURL + "/health")
	if err != nil {
		fmt.Println("wire is not running")
		os.Exit(1)
	}
	defer healthResp.Body.Close()

	var healthBody struct {
		Status string `json:"status"`
	}
	_ = json.NewDecoder(healthResp.Body).Decode(&healthBody)
	overall := healthBody.Status
	if overall == "" {
		if healthResp.StatusCode == http.StatusOK {
			overall = "healthy"
		} else {
			overall = "degraded"
		}
	}
	fmt.Printf("wire: %s (%s)\n", overall, baseURL)

	modelsResp, err := client.Get(baseURL + "/v1/models")
	if err != nil {
		return nil
	}
	defer modelsResp.Body.Close()

	var modelsBody struct {
		Data []struct {
			ID string `json:"id"`
		} `json:"data"`
	}
	if err := json.NewDecoder(modelsResp.Body).Decode(&modelsBody); err != nil {
		return nil
	}

	for _, m := range modelsBody.Data {
		b, ok := cfg.Backends[m.ID]
		model := m.ID
		if ok {
			if b.IsManaged() {
				model = b.Model
			} else {
				model = b.URL
			}
		}
		fmt.Printf("  %-14s %-40s %s\n", m.ID+":", model, overall)
	}
	return nil
}

func runSwap(backend, model string) error {
	cfg, err := config.Load()
	if err != nil {
		return fmt.Errorf("loading config: %w", err)
	}

	b, ok := cfg.Backends[backend]
	if !ok {
		return fmt.Errorf("backend %q not found in config", backend)
	}
	if b.IsExternal() {
		return fmt.Errorf("backend %q is external and cannot be swapped", backend)
	}

	b.Model = model
	cfg.Backends[backend] = b
	if err := config.WriteFile(cfg); err != nil {
		return err
	}

	pidPath := pidfile.Path()
	pid, err := pidfile.Read(pidPath)
	if err != nil {
		return err
	}
	proc, err := os.FindProcess(pid)
	if err != nil {
		return fmt.Errorf("finding process: %w", err)
	}
	if err := proc.Signal(syscall.SIGHUP); err != nil {
		return fmt.Errorf("sending SIGHUP to pid %d: %w", pid, err)
	}

	fmt.Printf("sent reload signal to wire (pid %d); run 'wire status' to check progress\n", pid)
	return nil
}

func runBuild(args []string) error {
	opts, err := build.DefaultOptions()
	if err != nil {
		return err
	}

	fs := flag.NewFlagSet("build", flag.ContinueOnError)
	fs.StringVar(&opts.Source, "source", opts.Source, "path to llama.cpp git checkout")
	fs.StringVar(&opts.GPUTarget, "gpu-target", opts.GPUTarget, "AMD GPU target (find yours: rocminfo | grep gfx)")
	fs.StringVar(&opts.Prefix, "prefix", opts.Prefix, "install prefix")
	if err := fs.Parse(args); err != nil {
		return err
	}

	return build.Build(opts)
}

func runRemove(args []string) error {
	opts, err := build.DefaultOptions()
	if err != nil {
		return err
	}

	fs := flag.NewFlagSet("remove", flag.ContinueOnError)
	fs.StringVar(&opts.Source, "source", opts.Source, "path to llama.cpp git checkout")
	if err := fs.Parse(args); err != nil {
		return err
	}

	return build.Remove(opts)
}

package gateway

import (
	"bytes"
	"context"
	"encoding/json"
	"io"
	"log/slog"
	"net/http"
	"net/http/httputil"
	"net/url"
	"strings"
	"sync"
	"time"

	"github.com/nogo/wire/internal/config"
	"github.com/nogo/wire/internal/monitor"
	"github.com/nogo/wire/internal/process"
	"github.com/nogo/wire/internal/translate/anthropic"
)

// backendManager is the subset of process.Manager the Gateway depends on.
type backendManager interface {
	Addr(name string) (string, bool)
	Healthy(name string) bool
}

// Gateway is an HTTP reverse-proxy that routes OpenAI-compatible requests to backends.
type Gateway struct {
	cfg    *config.Config
	mgr    backendManager
	log    *slog.Logger
	rt     *routeTable
	server *http.Server
}

// New creates a Gateway backed by the given process manager.
// hub may be nil; when non-nil, /monitor and /monitor/ws routes are registered.
func New(cfg *config.Config, mgr *process.Manager, hub *monitor.Hub, log *slog.Logger) *Gateway {
	return newGateway(cfg, mgr, hub, log)
}

func newGateway(cfg *config.Config, mgr backendManager, hub *monitor.Hub, log *slog.Logger) *Gateway {
	g := &Gateway{cfg: cfg, mgr: mgr, log: log, rt: buildRouteTable(cfg)}

	mux := http.NewServeMux()
	mux.HandleFunc("POST /v1/chat/completions", g.handleRoute)
	mux.HandleFunc("POST /v1/completions", g.handleRoute)
	mux.HandleFunc("POST /v1/embeddings", g.handleRoute)
	mux.HandleFunc("POST /v1/rerank", g.handleRoute)
	mux.HandleFunc("GET /v1/models", g.handleModels)
	mux.HandleFunc("GET /health", g.handleHealth)

	if hub != nil {
		mux.HandleFunc("GET /monitor", monitor.HandlePage)
		mux.HandleFunc("GET /monitor/ws", monitor.HandleWS(hub))
	}

	g.server = &http.Server{Addr: cfg.Listen, Handler: mux}
	return g
}

// ListenAndServe starts the HTTP server and shuts it down when ctx is cancelled.
func (g *Gateway) ListenAndServe(ctx context.Context) error {
	errCh := make(chan error, 1)
	go func() {
		if err := g.server.ListenAndServe(); err != nil && err != http.ErrServerClosed {
			errCh <- err
		}
	}()
	select {
	case err := <-errCh:
		return err
	case <-ctx.Done():
		shutCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
		defer cancel()
		return g.server.Shutdown(shutCtx)
	}
}

// handleRoute extracts the model field from the JSON body and proxies to the matching backend.
func (g *Gateway) handleRoute(w http.ResponseWriter, r *http.Request) {
	if len(g.cfg.Backends) == 0 {
		writeError(w, http.StatusInternalServerError, "server_error", "no backends configured", "no_backends")
		return
	}

	// Tee the body so the decoder and the upstream both see it.
	var captured bytes.Buffer
	tee := io.TeeReader(r.Body, &captured)
	dec := json.NewDecoder(tee)

	var payload struct {
		Model string `json:"model"`
	}
	if err := dec.Decode(&payload); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_request_error", "invalid JSON: "+err.Error(), "bad_request")
		return
	}
	if payload.Model == "" {
		writeError(w, http.StatusBadRequest, "invalid_request_error", "missing model field", "bad_request")
		return
	}

	// Reconstruct full body: captured bytes (read by decoder) + rest not yet read.
	r.Body = io.NopCloser(io.MultiReader(&captured, r.Body))

	backendName, err := g.rt.resolve(payload.Model)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_request_error", err.Error(), "model_not_found")
		return
	}

	if !g.mgr.Healthy(backendName) {
		writeError(w, http.StatusServiceUnavailable, "server_error", "backend unavailable", "backend_unavailable")
		return
	}

	addr, ok := g.mgr.Addr(backendName)
	if !ok {
		writeError(w, http.StatusServiceUnavailable, "server_error", "backend unavailable", "backend_unavailable")
		return
	}

	backend := g.cfg.Backends[backendName]
	if backend.Provider == "anthropic" {
		g.handleAnthropicProxy(w, r, backendName, backend, addr)
		return
	}

	target, parseErr := url.Parse(addr)
	if parseErr != nil {
		writeError(w, http.StatusInternalServerError, "server_error", "invalid backend URL", "internal_error")
		return
	}

	rewriter := g.buildReplacer(backendName)

	proxy := &httputil.ReverseProxy{
		Rewrite: func(pr *httputil.ProxyRequest) {
			pr.SetURL(target)
			pr.Out.Host = target.Host
		},
		FlushInterval: -1,
		ModifyResponse: func(resp *http.Response) error {
			if rewriter != nil {
				resp.Header.Del("Content-Length")
				resp.ContentLength = -1
				resp.Body = io.NopCloser(&replacingReader{r: resp.Body, repl: rewriter})
			}
			return nil
		},
		ErrorHandler: func(w http.ResponseWriter, _ *http.Request, err error) {
			g.log.Error("proxy error", "backend", backendName, "error", err)
			writeError(w, http.StatusBadGateway, "server_error", "upstream error: "+err.Error(), "upstream_error")
		},
	}

	proxy.ServeHTTP(w, r)
}

// handleAnthropicProxy translates the OpenAI-format request to Anthropic Messages API format,
// proxies it directly (without httputil.ReverseProxy), and translates the response back.
func (g *Gateway) handleAnthropicProxy(w http.ResponseWriter, r *http.Request, backendName string, backend config.Backend, addr string) {
	body, err := io.ReadAll(r.Body)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_request_error", "failed to read body", "bad_request")
		return
	}

	// Determine whether the client wants a streaming response.
	var meta struct {
		Stream bool `json:"stream"`
	}
	json.Unmarshal(body, &meta) //nolint:errcheck

	// model is either the configured model name (managed) or the backend name (external).
	model := backend.Model
	if model == "" {
		model = backendName
	}

	antBody, err := anthropic.TranslateRequest(body, model)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_request_error", "translation failed: "+err.Error(), "bad_request")
		return
	}

	antURL := strings.TrimRight(addr, "/") + "/v1/messages"
	antReq, err := http.NewRequestWithContext(r.Context(), http.MethodPost, antURL, bytes.NewReader(antBody))
	if err != nil {
		writeError(w, http.StatusInternalServerError, "server_error", "failed to build upstream request", "internal_error")
		return
	}
	antReq.Header.Set("content-type", "application/json")
	antReq.Header.Set("x-api-key", backend.APIKey)
	antReq.Header.Set("anthropic-version", "2023-06-01")

	resp, err := http.DefaultClient.Do(antReq)
	if err != nil {
		g.log.Error("anthropic upstream error", "backend", backendName, "error", err)
		writeError(w, http.StatusBadGateway, "server_error", "upstream error: "+err.Error(), "upstream_error")
		return
	}
	defer resp.Body.Close()

	if resp.StatusCode/100 != 2 {
		var buf bytes.Buffer
		buf.ReadFrom(resp.Body) //nolint:errcheck
		writeError(w, resp.StatusCode, "server_error", "upstream: "+strings.TrimSpace(buf.String()), "upstream_error")
		return
	}

	if meta.Stream {
		w.Header().Set("Content-Type", "text/event-stream")
		w.Header().Set("Cache-Control", "no-cache")
		w.Header().Set("Connection", "keep-alive")
		anthropic.TranslateStream(resp.Body, w, backendName)
		return
	}

	var buf bytes.Buffer
	buf.ReadFrom(resp.Body) //nolint:errcheck
	translated, err := anthropic.TranslateResponse(buf.Bytes(), backendName)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "server_error", "response translation failed: "+err.Error(), "internal_error")
		return
	}
	w.Header().Set("Content-Type", "application/json")
	w.Write(translated) //nolint:errcheck
}

// handleModels merges GET /v1/models from all backends and rewrites model IDs to backend names.
func (g *Gateway) handleModels(w http.ResponseWriter, r *http.Request) {
	type modelObj struct {
		ID      string `json:"id"`
		Object  string `json:"object"`
		Created int64  `json:"created"`
		OwnedBy string `json:"owned_by"`
	}
	type modelsResp struct {
		Object string     `json:"object"`
		Data   []modelObj `json:"data"`
	}

	var (
		mu   sync.Mutex
		data []modelObj
		wg   sync.WaitGroup
	)
	now := time.Now().Unix()

	for name := range g.cfg.Backends {
		name := name
		wg.Add(1)
		go func() {
			defer wg.Done()
			fallback := modelObj{ID: name, Object: "model", Created: now, OwnedBy: "wire"}

			addr, ok := g.mgr.Addr(name)
			if !ok {
				mu.Lock()
				data = append(data, fallback)
				mu.Unlock()
				return
			}

			ctx, cancel := context.WithTimeout(r.Context(), 5*time.Second)
			defer cancel()

			req, err := http.NewRequestWithContext(ctx, http.MethodGet, addr+"/v1/models", nil)
			if err != nil {
				mu.Lock()
				data = append(data, fallback)
				mu.Unlock()
				return
			}

			resp, err := http.DefaultClient.Do(req)
			if err != nil {
				mu.Lock()
				data = append(data, fallback)
				mu.Unlock()
				return
			}
			defer resp.Body.Close()

			var mr modelsResp
			if err := json.NewDecoder(resp.Body).Decode(&mr); err != nil || len(mr.Data) == 0 {
				mu.Lock()
				data = append(data, fallback)
				mu.Unlock()
				return
			}

			entry := mr.Data[0]
			entry.ID = name
			mu.Lock()
			data = append(data, entry)
			mu.Unlock()
		}()
	}
	wg.Wait()

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(modelsResp{Object: "list", Data: data}) //nolint:errcheck
}

// handleHealth returns 200 if at least one backend is healthy, 503 otherwise.
func (g *Gateway) handleHealth(w http.ResponseWriter, _ *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	for name := range g.cfg.Backends {
		if g.mgr.Healthy(name) {
			w.WriteHeader(http.StatusOK)
			json.NewEncoder(w).Encode(map[string]string{"status": "ok"}) //nolint:errcheck
			return
		}
	}
	w.WriteHeader(http.StatusServiceUnavailable)
	json.NewEncoder(w).Encode(map[string]string{"status": "degraded"}) //nolint:errcheck
}

// buildReplacer creates a strings.Replacer that rewrites llama-server model name aliases
// in response bodies to the canonical backend name.
func (g *Gateway) buildReplacer(backendName string) *strings.Replacer {
	aliases := g.rt.backendAliases[backendName]
	var pairs []string
	for _, alias := range aliases {
		if alias == backendName {
			continue
		}
		pairs = append(pairs,
			`"model":"`+alias+`"`, `"model":"`+backendName+`"`,
		)
	}
	if len(pairs) == 0 {
		return nil
	}
	return strings.NewReplacer(pairs...)
}

// replacingReader wraps an io.Reader and applies a strings.Replacer to each chunk read.
// Overflow bytes (when replacement expands the chunk) are buffered internally.
type replacingReader struct {
	r    io.Reader
	repl *strings.Replacer
	buf  bytes.Buffer
}

func (rr *replacingReader) Read(p []byte) (int, error) {
	if rr.buf.Len() > 0 {
		return rr.buf.Read(p)
	}
	tmp := make([]byte, len(p))
	n, readErr := rr.r.Read(tmp)
	if n > 0 {
		replaced := []byte(rr.repl.Replace(string(tmp[:n])))
		copy(p, replaced)
		if len(replaced) > len(p) {
			rr.buf.Write(replaced[len(p):])
			return len(p), nil // defer readErr until buf is drained
		}
		return len(replaced), readErr
	}
	return 0, readErr
}

// writeError writes an OpenAI-format JSON error response.
func writeError(w http.ResponseWriter, status int, errType, message, code string) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	json.NewEncoder(w).Encode(map[string]any{ //nolint:errcheck
		"error": map[string]any{
			"message": message,
			"type":    errType,
			"code":    code,
		},
	})
}

